const fold=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),PAGE_SIZE=24;
export function favoriteEntries(g,query=''){
 const grouped=new Map();for(const key of g.state.roster){const d=g.dex[parseInt(key)];if(!d||key.endsWith('s')&&!d.shiny)continue;let entry=grouped.get(d.id);if(!entry){entry={id:d.id,name:d.name,rarity:d.rarity,keys:[]};grouped.set(d.id,entry)}if(!entry.keys.includes(key))entry.keys.push(key)}
 const q=fold(query).trim();return [...grouped.values()].filter(e=>!q||fold(e.name+' '+e.id+' #'+String(e.id).padStart(3,'0')+(e.keys.some(k=>k.endsWith('s'))?' chromatique shiny':'')).includes(q)).sort((a,b)=>a.name.localeCompare(b.name,'fr'));
}
export function ownedFavorite(g,key){return favoriteEntries(g).flatMap(e=>e.keys).includes(key)?key:favoriteEntries(g)[0]?.keys[0]||''}
export function favoriteField(g,p){const key=ownedFavorite(g,p.favorite),d=key?g.dex[parseInt(key)]:null;p.favorite=key;return `<div class="favorite-field"><span>Pokémon préféré</span><input type="hidden" id="profile-favorite" value="${key}"><div class="favorite-preview">${d?`<canvas width="130" height="105" data-mon="${key}" aria-label="${g.escape(d.name)}"></canvas><div><b>${g.escape(d.name)}</b><small>${key.endsWith('s')?'✧ Chromatique':'Apparence normale'} · Obtenu</small></div>`:'<p>Tu n’as pas encore de Pokémon disponible.</p>'}<button data-act="favorite-toggle" aria-expanded="${!!g.favoritePickerOpen}" aria-controls="favorite-chooser">${g.favoritePickerOpen?'Fermer':'Choisir un Pokémon'} ${g.favoritePickerOpen?'↑':'↓'}</button></div></div>`}
export function favoriteGrid(g,p){if(!g.favoritePickerOpen)return '';const entries=favoriteEntries(g,g.favoriteQuery||''),pages=Math.max(1,Math.ceil(entries.length/PAGE_SIZE));g.favoritePage=Math.max(0,Math.min(g.favoritePage||0,pages-1));return `<section class="favorite-chooser" id="favorite-chooser" aria-label="Choisir parmi mes Pokémon obtenus"><div class="favorite-search-row"><div><h3>Choisis parmi tes Pokémon</h3><p>Uniquement tes compagnons obtenus. Clique sur le sprite ou sur une apparence disponible.</p></div><input type="search" id="favorite-search" value="${g.escape(g.favoriteQuery||'')}" placeholder="Nom ou numéro du Pokémon…" aria-label="Rechercher un Pokémon obtenu"></div><p class="favorite-count" role="status">${entries.length} espèce${entries.length>1?'s':''} · Page ${g.favoritePage+1} / ${pages}</p><div class="favorite-grid">${entries.slice(g.favoritePage*PAGE_SIZE,(g.favoritePage+1)*PAGE_SIZE).map(e=>{const preferred=String(e.id)+(g.state.pokemonVariants?.[e.id]==='shiny'?'s':''),key=e.keys.includes(p.favorite)?p.favorite:e.keys.includes(preferred)?preferred:e.keys[0],selected=e.keys.includes(p.favorite);return `<article class="favorite-option ${selected?'selected':''}" data-favorite-species="${e.id}"><button class="favorite-mon" data-act="favorite-select" data-key="${key}" aria-pressed="${selected}"><small>#${String(e.id).padStart(3,'0')}</small><canvas width="130" height="105" data-mon="${key}" aria-label="${g.escape(e.name)}${key.endsWith('s')?' chromatique':''}"></canvas><b>${g.escape(e.name)}</b><span>${selected?'✓ Choisi':key.endsWith('s')?'✧ Chromatique':'Normal'}</span></button><div class="favorite-variants" role="group" aria-label="Apparences obtenues de ${g.escape(e.name)}">${e.keys.slice().sort((a,b)=>a.endsWith('s')-b.endsWith('s')).map(k=>`<button data-act="favorite-select" data-key="${k}" aria-pressed="${p.favorite===k}" class="${p.favorite===k?'selected':''}">${k.endsWith('s')?'✧ Chromatique':'Normal'}</button>`).join('')}</div></article>`}).join('')||'<p class="favorite-empty">Aucun de tes Pokémon ne correspond à cette recherche.</p>'}</div><div class="avatar-pages"><button data-act="favorite-page" data-page="${g.favoritePage-1}" ${!g.favoritePage?'disabled':''}>← Précédents</button><span>${g.favoritePage+1} / ${pages}</span><button data-act="favorite-page" data-page="${g.favoritePage+1}" ${g.favoritePage>=pages-1?'disabled':''}>Suivants →</button></div></section>`}
